      SUBROUTINE PARTRJCC     CALCULATES PARTIALS OF THIRD-ORDER MATRIX OF A SINGLE BEAMC     ELEMENT WITH RESPECT TO THE VARIED QUANTITYCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESC      INTEGER         IND, IX, K, MC-------------------------------------------------------------------------------C      GO TO (5000, 200, 300, 400, 500,5000,5000,5000,5000,5000,     1       5000,5000,5000,1400,5000,5000,5000,1800,1900,5000,     2       5000,5000,5000,5000,2500,5000,5000,5000,5000,5000,     3       5000,5000,5000,3400,3500,3500,5000,5000,5000,5000,     4       5000,5000,5000,5000,5000,5000,5000,5000), TYPECCC     2. -- POLE FACE ROTATIONC  200 CONTINUE      GO TO 5000CC     3. -- DRIFT SPACEC  300 CONTINUE      GO TO 5000CC     4. -- BENDING MAGNETC  400 CALL DBEND3      GO TO 5000CC     5. -- QUADRUPOLEC  500 IF (JV .EQ. 2 .OR. JV .EQ. 4 .OR. JV .EQ. 5) GO TO 520      JQUAD = 1      KQ2 = KX2      CALL DFOL3      JQUAD = 3      KQ2 = KY2      CALL DFOL3      GO TO 5000C  520 JQUAD = 1      KQ2 = KX2      CALL DFOCU3      JQUAD = 3      KQ2 = KY2      KVK = - KVK      CALL DFOCU3      KVK = - KVK      GO TO 5000CC     14. -- ARBITRARY MATRIXC 1400 IF (I14T .NE. 0) GO TO 1420      IX = I + 30      IND = 0      DO 1410 J = 1, 6      DO 1410 K = J, 6      DO 1410 M = K, 6      IX = IX + 1      IND = IND + 1      UV(J1,IND) = UBEAM(J1)/(UBEAM(J)*UBEAM(K)*UBEAM(M)) 1410 CONTINUE 1420 IF (NUM + 1 .LE. NEL) THEN        IF (NEXT .EQ. 14) RETURN      ENDIF      GO TO 5000CC     18. -- SEXTUPOLEC 1800 CALL DSEXT3      GO TO 5000CC     19. -- SOLENOIDC 1900 CONTINUE      GO TO 5000CC     25. -- OCTUPOLEC 2500 IF (SOFA) LINEAR = .FALSE.      CALL DOCTPL      GO TO 5000CC     34. -- PLASMA LENSC 3400 CONTINUE      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 CONTINUE      GO TO 5000C 5000 CONTINUE      RETURN      END